import { Component,AfterViewInit,ViewChild,ElementRef  } from '@angular/core';
import { routes } from 'src/app/core/helpers/routes';
import { users,tickets,messages } from 'src/app/shared/model/page.model';
import {
  DataService,apiResultFormat
} from 'src/app/core/core.index';
import { NgScrollbar } from 'ngx-scrollbar';

@Component({
  selector: 'app-chat',
  templateUrl: './chat.component.html',
  styleUrls: ['./chat.component.scss'],
})


export class ChatComponent implements AfterViewInit{
  @ViewChild('chatContainer') private chatContainer!: ElementRef;

  public usersData: Array<users> = [];
  public ticketsData: Array<tickets> = [];
  public messagesData: Array<messages> = [];
  public selectedUser: { userId: number; name: string;profile_img_url: string } | null = null;
  public selectedTicketId: number = 0;
  public selectedTicketMessage: string = '';
  public showMessages: boolean = false;
  messageText: string = '';
  public routes = routes;
 constructor(    
  private data: DataService
  ) {
  this.getUsersData()
  }
  ngAfterViewInit(): void {
    this.scrollToBottom();
  }

  scrollToBottom(): void {
    setTimeout(() => {
      this.chatContainer.nativeElement.scrollTop = this.chatContainer.nativeElement.scrollHeight;
    }, 100);
  }
    private getUsersData(): void {
      this.data.getMessagesUsers().subscribe((apiRes: apiResultFormat) => {
        console.log(apiRes)
        this.usersData = [];
        apiRes.data.forEach((res: users, index: number) => {
          // Push data to the table array
          this.usersData.push({
            ...res
          });
        });
      });
    }
    private getTicketsData(userId: number, name: string): void {

      if(userId)
      this.data.getTicketsByUserId(userId).subscribe((apiRes: any) => {
        this.ticketsData = [];
        this.ticketsData =apiRes.results.tickets
      });
    }
    private getMessagesData(ticketId: number): void {

      if(ticketId)
      this.data.getMessagesByTicketId(ticketId).subscribe((apiRes: any) => {
        this.messagesData = [];
        this.messagesData =apiRes.results.messages
      });
    }
    selectUser(user:any): void {

      this.getTicketsData(user.user_id,user.first_name + " " + user.last_name)
      this.selectedUser={
        userId: user.user_id,
        name: (user.first_name||"-") + " " + (user.last_name ||"-"),
        profile_img_url: user.profile_img_url
      }
    }
    selectTicket(ticket:any,event:string): void {
      if(event=='show'){
        this.getMessagesData(ticket.ticket_id)
        this.selectedTicketId = ticket.ticket_id
        this.selectedTicketMessage = ticket.subject
        this.showMessages=true
      }
      else{
        this.showMessages=false
      }
    }
    submitMessage(): void {
      if (!this.messageText.trim()) {
        console.warn('Message cannot be empty');
        return;
      }
      if(this.messageText != '')
      this.data.submitMessage(this.selectedTicketId, this.messageText).subscribe((apiRes: any) => {
        this.getMessagesData(this.selectedTicketId)
        this.messageText = '';
      });
    }
}
